// Filter: only process records where status === 'monitoring'
// (new deployments land with status='monitoring')
const record = $input.item.json;
const fields = record.fields || record;

if (fields.status !== 'monitoring') {
  return []; // stop execution — not a new deployment
}

console.log('New deployment detected:', fields.deployment_id);

return [{
  json: {
    deployment_id: fields.deployment_id,
    release_version: fields.release_version,
    deploying_team: fields.deploying_team,
    release_datetime: fields.release_datetime,
    triggered_at: new Date().toISOString()
  }
}];
